/* Parecer de acompanhamento para a gestão — gerado a partir de window.PEONA_DATA. */
(function () {
  const LOGO_CLARO = "data:image/png;base64,";
  const LAGS = [
    { j: 0, nome: "Mesmo mês", leitura: "eventos ocorridos e avisados no próprio mês" },
    { j: 1, nome: "Mês seguinte", leitura: "eventos do mês anterior, avisados com um mês de atraso" },
    { j: 2, nome: "Dois meses", leitura: "eventos avisados com dois meses de atraso" },
    { j: 3, nome: "Três meses", leitura: "eventos avisados com três meses de atraso" },
    { j: 4, nome: "Quatro meses", leitura: "eventos avisados com quatro meses de atraso" },
    { j: 5, nome: "Cinco meses ou mais", leitura: "cauda de atrasos de cinco meses ou mais" },
  ];

  function dados() {
    if (!window.PEONA_DATA) throw new Error("Dados não carregados.");
    return window.PEONA_DATA;
  }

  function esc(s) {
    return String(s ?? "")
      .replaceAll("&", "&amp;")
      .replaceAll("<", "&lt;")
      .replaceAll(">", "&gt;")
      .replaceAll('"', "&quot;");
  }

  function num(v) {
    const n = Number(v);
    return Number.isFinite(n) ? n : null;
  }

  function brl(v) {
    const n = num(v);
    if (n == null) return "—";
    return n.toLocaleString("pt-BR", { style: "currency", currency: "BRL" });
  }

  function brlMi(v) {
    const n = num(v);
    if (n == null) return "—";
    const mi = n / 1e6;
    const abs = Math.abs(mi);
    const texto = abs.toLocaleString("pt-BR", { minimumFractionDigits: 1, maximumFractionDigits: 1 });
    return (mi < 0 ? "−" : "") + "R$ " + texto + " milhões";
  }

  function pct(v, dig = 1) {
    const n = num(v);
    if (n == null) return "—";
    return (n * 100).toLocaleString("pt-BR", {
      minimumFractionDigits: dig,
      maximumFractionDigits: dig,
    }) + "%";
  }

  function pp(v) {
    const n = num(v);
    if (n == null) return "—";
    const sinal = n > 0 ? "+" : "";
    return sinal + (n * 100).toLocaleString("pt-BR", {
      minimumFractionDigits: 1,
      maximumFractionDigits: 1,
    }) + " p.p.";
  }

  function mesLabel(iso) {
    if (!iso) return "—";
    const [y, m] = String(iso).slice(0, 10).split("-");
    const nomes = ["jan", "fev", "mar", "abr", "mai", "jun", "jul", "ago", "set", "out", "nov", "dez"];
    return `${nomes[Number(m) - 1]}/${y}`;
  }

  function dataEmissao(iso) {
    if (!iso) return "—";
    const d = new Date(iso);
    if (Number.isNaN(d.getTime())) return String(iso).slice(0, 10);
    return d.toLocaleString("pt-BR", { dateStyle: "long", timeStyle: "short" });
  }

  function serie(tipo, janela) {
    return (dados().serie || [])
      .filter((r) => r.tipo === tipo && Number(r.janela) === janela)
      .slice()
      .sort((a, b) => String(a.competencia).localeCompare(String(b.competencia)));
  }

  function serieGeral(janela) {
    const mh = serie("MH", janela);
    const odPor = new Map(serie("OD", janela).map((r) => [r.competencia, r]));
    return mh.map((m) => {
      const o = odPor.get(m.competencia);
      const avisoM = num(m.total_avisado) || 0;
      const avisoO = num(o && o.total_avisado) || 0;
      const aviso = avisoM + avisoO;
      const media = (num(m.media_nm) || 0) + (num(o && o.media_nm) || 0);
      const peona = (num(m.peona) || 0) + (num(o && o.peona) || 0);
      const row = {
        competencia: m.competencia,
        total_avisado: aviso,
        media_nm: media,
        peona,
        fator_peona: media ? peona / media : null,
      };
      LAGS.forEach(({ j }) => {
        const mkM = mk(m, j);
        const mkO = o ? mk(o, j) : null;
        const pesoM = mkM == null ? 0 : avisoM;
        const pesoO = mkO == null ? 0 : avisoO;
        const peso = pesoM + pesoO;
        row[`Mk${j}`] = peso ? (mkM * pesoM + (mkO || 0) * pesoO) / peso : mkM;
      });
      return row;
    });
  }

  function mk(row, j) {
    return num(row?.[`Mk${j}`]);
  }

  function mediaMk(rows) {
    return LAGS.map(({ j }) => {
      const vals = rows.map((r) => mk(r, j)).filter((v) => v != null);
      if (!vals.length) return null;
      return vals.reduce((a, b) => a + b, 0) / vals.length;
    });
  }

  function addMeses(iso, delta) {
    const [y, m] = String(iso).slice(0, 10).split("-").map(Number);
    const d = new Date(y, m - 1 + delta, 1);
    const mm = String(d.getMonth() + 1).padStart(2, "0");
    return `${d.getFullYear()}-${mm}-01`;
  }

  function achar(rows, iso) {
    return rows.find((r) => r.competencia === iso) || null;
  }

  function variacao(atual, anterior, campo) {
    const a = num(atual?.[campo]);
    const b = num(anterior?.[campo]);
    if (a == null || b == null || b === 0) return null;
    return a / b - 1;
  }

  function direcao(v) {
    if (v == null || Math.abs(v) < 0.005) return "ficou estável";
    return v > 0 ? "aumentou" : "recuou";
  }

  function fraseVariacao(v) {
    if (v == null) return "sem base de comparação";
    if (Math.abs(v) < 0.005) return "praticamente estável";
    return (v > 0 ? "alta de " : "queda de ") + pct(Math.abs(v));
  }

  function efeitos(atual, anterior) {
    const bk0 = num(anterior.media_nm);
    const bk1 = num(atual.media_nm);
    const ik0 = num(anterior.fator_peona);
    const ik1 = num(atual.fator_peona);
    if ([bk0, bk1, ik0, ik1].some((v) => v == null)) return null;
    return {
      base: (bk1 - bk0) * ik0,
      fator: (ik1 - ik0) * bk1,
      peona: num(atual.peona) - num(anterior.peona),
    };
  }

  function sequenciaAltas(rows, campo, n) {
    const fatia = rows.slice(-n);
    if (fatia.length < 3) return null;
    let altas = 0;
    for (let i = 1; i < fatia.length; i++) {
      const d = variacao(fatia[i], fatia[i - 1], campo);
      if (d != null && d > 0.01) altas += 1;
    }
    return {
      meses: fatia.length - 1,
      altas,
      inicio: fatia[0],
      fim: fatia[fatia.length - 1],
      variacao: variacao(fatia[fatia.length - 1], fatia[0], campo),
    };
  }

  function deslocamentos(atualMk, baseMk) {
    return LAGS.map((lag, i) => ({
      ...lag,
      atual: atualMk[i],
      base: baseMk[i],
      delta: atualMk[i] != null && baseMk[i] != null ? atualMk[i] - baseMk[i] : null,
    })).filter((x) => x.delta != null);
  }

  function maiorDeslocamento(lista) {
    return lista.slice().sort((a, b) => Math.abs(b.delta) - Math.abs(a.delta))[0] || null;
  }

  function janelaChave(r) {
    if (r.janela === "6m" || r.janela === "12m") return r.janela;
    if (Number(r.janela_meses) === 6) return "6m";
    if (Number(r.janela_meses) === 12) return "12m";
    return "";
  }

  function janelaOficialDoTeste(r) {
    const meta = dados().consistencia_meta || {};
    const inicio6 = meta.inicio_6m || "2025-10-01";
    const comp = r.competencia_teste || r.competencia || "";
    return comp >= inicio6 ? "6m" : "12m";
  }

  function testesRecentes() {
    const rows = (dados().consistencia || []).filter(
      (r) => janelaChave(r) === janelaOficialDoTeste(r)
    );
    const chaves = [...new Set(rows.map((r) => r.competencia_teste).filter(Boolean))].sort();
    const ultimos = chaves.slice(-2);
    return agregarTestes(rows.filter((r) => ultimos.includes(r.competencia_teste)));
  }

  function agregarTestes(rows) {
    const grupos = new Map();
    rows.forEach((r) => {
      const chave = r.competencia_teste || r.competencia;
      if (!grupos.has(chave)) grupos.set(chave, []);
      grupos.get(chave).push(r);
    });
    return [...grupos.values()].map((lista) => {
      const est = lista.reduce((s, r) => s + (num(r.peona_estimada) || 0), 0);
      const real = lista.reduce((s, r) => s + (num(r.peona_real) || 0), 0);
      const difPct = real ? (est - real) / real : null;
      const peso = lista.reduce((s, r) => s + Math.abs(num(r.peona_estimada) || 0), 0);
      const media =
        peso && lista.every((r) => num(r.variacao_media) != null)
          ? lista.reduce((s, r) => s + num(r.variacao_media) * Math.abs(num(r.peona_estimada) || 0), 0) / peso
          : null;
      const base = lista[0];
      const dentro = (v, inf, sup) => v != null && inf != null && sup != null && v >= inf && v <= sup;
      const mensalOk = dentro(difPct, num(base.ans_mensal_inf), num(base.ans_mensal_sup));
      const mediaOk = media == null || dentro(media, num(base.ans_media_inf), num(base.ans_media_sup));
      const ok = mensalOk && mediaOk;
      return {
        competencia_teste: base.competencia_teste || base.competencia,
        janela: base.janela,
        peona_estimada: est,
        peona_real: real,
        diferenca_pct: difPct,
        status: ok ? "consistente" : "nao_consistente",
        status_rotulo: ok ? "Consistente" : "Não consistente",
        status_mensagem: ok
          ? "A PEONA geral ficou dentro dos limites da ANS."
          : "A PEONA geral ficou fora de um dos limites da ANS.",
      };
    });
  }

  function montarAlertas(ctx) {
    const alertas = [];
    const { atual, anterior, anoAntes, seq, shifts, testes } = ctx;

    const varMes = variacao(atual, anterior, "total_avisado");
    const seqCobreOMes = seq && seq.fim === atual && seq.altas >= seq.meses - 1 && seq.variacao >= 0.05;
    if (varMes != null && varMes >= 0.05 && !seqCobreOMes) {
      alertas.push({
        nivel: "alto",
        titulo: "A despesa assistencial avisada aumentou no mês",
        texto:
          `Em ${mesLabel(atual.competencia)} a despesa assistencial avisada foi ${brlMi(atual.total_avisado)}, ` +
          `${fraseVariacao(varMes)} em relação a ${mesLabel(anterior.competencia)} (${brlMi(anterior.total_avisado)}). ` +
          "Esse é o volume que entra na base da PEONA. Quando o aviso sobe, a provisão sobe junto, ainda que o fator de atraso não mude.",
      });
    }

    const varAno = variacao(atual, anoAntes, "total_avisado");
    if (varAno != null && Math.abs(varAno) >= 0.08) {
      alertas.push({
        nivel: varAno > 0 ? "alto" : "atencao",
        titulo: "A despesa assistencial avisada mudou em doze meses",
        texto:
          `Contra ${mesLabel(anoAntes.competencia)}, a despesa assistencial avisada ${direcao(varAno)} ${pct(Math.abs(varAno))} ` +
          `(de ${brlMi(anoAntes.total_avisado)} para ${brlMi(atual.total_avisado)}). ` +
          "Esta é a variação do custo assistencial avisado do plano, médico-hospitalar e odontológico juntos. " +
          "A leitura é do valor total avisado, não de um custo por beneficiário.",
      });
    }

    if (seq && seq.altas >= seq.meses - 1 && seq.variacao != null && seq.variacao >= 0.05) {
      alertas.push({
        nivel: "alto",
        titulo: "As despesas avisadas vêm aumentando em sequência",
        texto:
          `Nos últimos ${seq.meses} intervalos, a despesa assistencial avisada subiu em ${seq.altas}. ` +
          `De ${mesLabel(seq.inicio.competencia)} a ${mesLabel(seq.fim.competencia)} o acumulado foi ${fraseVariacao(seq.variacao)}. ` +
          "Uma sequência assim pesa no custo do plano e na provisão, porque a base média da janela de seis meses incorpora cada mês mais alto.",
      });
    }

    const mk0 = mk(atual, 0);
    const mk1 = mk(atual, 1);
    if (mk0 != null && mk1 != null && mk0 < 0.15 && mk1 >= 0.5) {
      const antes =
        anoAntes
          ? ` Há um ano, em ${mesLabel(anoAntes.competencia)}, o mesmo mês pesava ${pct(mk(anoAntes, 0))} e o mês seguinte ${pct(mk(anoAntes, 1))}.`
          : "";
      alertas.push({
        nivel: "alto",
        titulo: "A maior parte do aviso chega no mês seguinte ao evento",
        texto:
          `Nesta competência, ${pct(mk0)} da composição do atraso está no mesmo mês do aviso e ${pct(mk1)} no mês seguinte. ` +
          "A despesa do plano chega sobretudo com um mês de defasagem." +
          antes +
          " Enquanto esse desenho se mantém, a PEONA precisa cobrir uma cauda grande já no primeiro mês depois da ocorrência.",
      });
    }

    const forte = shifts.filter((s) => Math.abs(s.delta) >= 0.08);
    if (forte.length) {
      const sobe = forte.filter((s) => s.delta > 0).sort((a, b) => b.delta - a.delta)[0];
      const desce = forte.filter((s) => s.delta < 0).sort((a, b) => a.delta - b.delta)[0];
      const partes = [];
      if (desce) {
        partes.push(
          `antes, ${desce.leitura} representavam ${pct(desce.base)} da composição do atraso; agora representam ${pct(desce.atual)}`
        );
      }
      if (sobe) {
        partes.push(
          `a faixa que ganhou peso foi “${sobe.nome}” (${sobe.leitura}), que passou de ${pct(sobe.base)} para ${pct(sobe.atual)}`
        );
      }
      alertas.push({
        nivel: "alto",
        titulo: "O ritmo do aviso mudou",
        texto:
          `Na comparação com a média dos seis meses anteriores, ${partes.join("; ")}. ` +
          "Quando o aviso deixa de cair no mesmo mês e se concentra no mês seguinte, o fechamento enxerga menos despesa do próprio mês e uma cauda maior. " +
          "A PEONA reage a esse desenho, não só ao valor avisado.",
      });
    }

    const ruins = testes.filter((t) => t.status === "nao_consistente");
    if (ruins.length) {
      const pior = ruins.slice().sort((a, b) => Math.abs(num(b.diferenca_pct) || 0) - Math.abs(num(a.diferenca_pct) || 0))[0];
      alertas.push({
        nivel: "atencao",
        titulo: "O teste de consistência da PEONA saiu do parâmetro",
        texto:
          `No teste de ${mesLabel(pior.competencia_teste)} (janela ${esc(pior.janela)}), a PEONA estimada foi ${brlMi(pior.peona_estimada)} ` +
          `e o run-off depois observado foi ${brlMi(pior.peona_real)} (${fraseVariacao(pior.diferenca_pct)}). ` +
          `${pior.status_mensagem || "Um dos critérios da ANS ficou fora do intervalo."} ` +
          "Para a gestão, isso indica que a provisão daquele mês não reproduziu o que a despesa tardia confirmou.",
      });
    }

    if (!alertas.length) {
      alertas.push({
        nivel: "info",
        titulo: "Sem deslocamento material nesta competência",
        texto:
          "A despesa avisada, o fator de atraso e a composição do aviso não cruzaram os limites usados neste acompanhamento. " +
          "O detalhe numérico está nas seções seguintes.",
      });
    }
    return alertas;
  }

  function htmlAlertas(alertas) {
    return alertas
      .map(
        (a) => `<article class="alerta nivel-${a.nivel}">
          <p class="alerta-nivel">${a.nivel === "alto" ? "Alerta" : a.nivel === "atencao" ? "Atenção" : "Informação"}</p>
          <h3>${esc(a.titulo)}</h3>
          <p>${esc(a.texto)}</p>
        </article>`
      )
      .join("");
  }

  function htmlTabelaMh(rows, anteriorAoPrimeiro) {
    const corpo = rows
      .map((r, i) => {
        const ant = i > 0 ? rows[i - 1] : anteriorAoPrimeiro;
        return `<tr>
          <td>${esc(mesLabel(r.competencia))}</td>
          <td class="num">${esc(brlMi(r.total_avisado))}</td>
          <td class="num">${esc(fraseVariacao(variacao(r, ant, "total_avisado")))}</td>
          <td class="num">${esc(brlMi(r.media_nm))}</td>
          <td class="num">${esc(pct(r.fator_peona, 2))}</td>
          <td class="num">${esc(brlMi(r.peona))}</td>
        </tr>`;
      })
      .join("");
    return `<table class="tabela">
      <thead><tr>
        <th>Competência</th>
        <th>Despesa avisada</th>
        <th>Variação do aviso</th>
        <th>Base média (6 meses)</th>
        <th>Fator de atraso</th>
        <th>PEONA</th>
      </tr></thead>
      <tbody>${corpo}</tbody>
    </table>`;
  }

  function htmlTabelaMk(shifts) {
    const corpo = shifts
      .map(
        (s) => `<tr>
        <td>${esc(s.nome)}</td>
        <td>${esc(s.leitura)}</td>
        <td class="num">${esc(pct(s.base))}</td>
        <td class="num">${esc(pct(s.atual))}</td>
        <td class="num">${esc(pp(s.delta))}</td>
      </tr>`
      )
      .join("");
    return `<table class="tabela">
      <thead><tr>
        <th>Atraso do aviso</th>
        <th>O que significa</th>
        <th>Média dos 6 meses anteriores</th>
        <th>Competência atual</th>
        <th>Diferença</th>
      </tr></thead>
      <tbody>${corpo}</tbody>
    </table>`;
  }

  function paragrafoDecomposicao(atual, anterior, fx) {
    if (!anterior || !fx) {
      return "<p>Ainda não há competência anterior para separar o efeito da base de avisos e o efeito do fator de atraso.</p>";
    }
    const varPeona = variacao(atual, anterior, "peona");
    const sinalBase = fx.base >= 0 ? "elevou" : "reduziu";
    const sinalFator = fx.fator >= 0 ? "elevou" : "reduziu";
    return `<p>A PEONA do plano passou de ${esc(brlMi(anterior.peona))} em ${esc(mesLabel(anterior.competencia))} para ${esc(brlMi(atual.peona))} em ${esc(mesLabel(atual.competencia))} (${esc(fraseVariacao(varPeona))}). O valor junta médico-hospitalar e odontológico.</p>
      <p>Dois movimentos se somam. A base média de avisos ${sinalBase} a provisão em ${esc(brlMi(Math.abs(fx.base)))}. O fator de atraso ${sinalFator} a provisão em ${esc(brlMi(Math.abs(fx.fator)))}. O fator saiu de ${esc(pct(anterior.fator_peona, 2))} para ${esc(pct(atual.fator_peona, 2))}.</p>
      <p>Em linguagem de gestão: a primeira parcela é a despesa que já chegou mais alta; a segunda é a mudança de quanto ainda se espera avisado para cada real da base. Quando as duas sobem juntas, a despesa assistencial e a provisão pressionam o plano ao mesmo tempo.</p>`;
  }

  function paragrafoMk(atual, shifts, anoAntes) {
    const principal = maiorDeslocamento(shifts);
    let texto =
      `<p>A composição abaixo é a participação de cada atraso no fator da janela de seis meses. ` +
      `A referência é a média de ${esc(mesLabel(shifts.inicioBase))} a ${esc(mesLabel(shifts.fimBase))}.</p>`;
    if (principal && Math.abs(principal.delta) >= 0.03) {
      texto +=
        `<p>O maior deslocamento está em “${esc(principal.nome)}”: ${esc(pct(principal.base))} na média anterior e ${esc(pct(principal.atual))} agora (${esc(pp(principal.delta))}). ` +
        `${esc(principal.leitura.charAt(0).toUpperCase() + principal.leitura.slice(1))}.</p>`;
    }
    if (anoAntes) {
      const mk0a = mk(anoAntes, 0);
      const mk1a = mk(anoAntes, 1);
      const mk0 = mk(atual, 0);
      const mk1 = mk(atual, 1);
      texto +=
        `<p>Há doze meses, em ${esc(mesLabel(anoAntes.competencia))}, o mesmo mês do aviso pesava ${esc(pct(mk0a))} e o mês seguinte ${esc(pct(mk1a))}. ` +
        `Nesta competência, o mesmo mês pesa ${esc(pct(mk0))} e o mês seguinte ${esc(pct(mk1))}. ` +
        "Essa troca de peso é o sinal de que o aviso mudou de calendário.</p>";
    }
    return texto;
  }

  function htmlConsistencia(testes) {
    if (!testes.length) {
      return "<p>Não há teste de consistência recente no painel.</p>";
    }
    const lista = testes.slice().sort((a, b) => String(a.competencia_teste).localeCompare(String(b.competencia_teste)));
    const corpo = lista
      .map(
        (t) => `<tr>
        <td>${esc(mesLabel(t.competencia_teste))}</td>
        <td>${esc(t.janela || "—")}</td>
        <td class="num">${esc(brlMi(t.peona_estimada))}</td>
        <td class="num">${esc(brlMi(t.peona_real))}</td>
        <td class="num">${esc(pct(t.diferenca_pct))}</td>
        <td>${esc(t.status_rotulo || t.status || "—")}</td>
      </tr>`
      )
      .join("");
    return `<p>O teste compara a PEONA que foi estimada com o run-off que a base mostrou depois. Os valores da tabela são a PEONA geral, já somados o médico-hospitalar e o odontológico. A defasagem do painel é de três meses: a competência testada não é a competência que está sendo apurada agora. Até setembro de 2025 a janela oficial do teste é de 12 meses. A partir de outubro de 2025, o teste oficial é o de 6 meses.</p>
      <table class="tabela">
        <thead><tr>
          <th>Competência testada</th>
          <th>Janela</th>
          <th>PEONA estimada</th>
          <th>Run-off observado</th>
          <th>Diferença</th>
          <th>Leitura</th>
        </tr></thead>
        <tbody>${corpo}</tbody>
      </table>`;
  }

  function conclusao(ctx, alertas) {
    const altos = alertas.filter((a) => a.nivel === "alto");
    const { atual, anterior } = ctx;
    const varMes = variacao(atual, anterior, "total_avisado");
    const abertura =
      varMes != null && varMes >= 0.05
        ? `A despesa assistencial avisada está mais alta em ${mesLabel(atual.competencia)}.`
        : `A despesa assistencial avisada em ${mesLabel(atual.competencia)} foi ${brlMi(atual.total_avisado)}.`;
    const foco = altos.length
      ? " Os pontos que pedem decisão da gestão estão na síntese: volume avisado, sequência de altas e mudança do calendário do aviso."
      : " Não há, nesta competência, um deslocamento que isoladamente explique uma aceleração forte do custo.";
    return `<p>${esc(abertura)}${esc(foco)}</p>
      <p>A PEONA de ${esc(mesLabel(atual.competencia))} fecha em ${esc(brlMi(atual.peona))}, já somados o médico-hospitalar e o odontológico, na janela de seis meses. Ela acompanha a despesa que já foi avisada e o quanto o padrão de atraso ainda projeta para a frente. Se o aviso continua migrando para o mês seguinte, a provisão permanece elevada mesmo num mês em que o evento assistencial do próprio mês ainda não apareceu por completo.</p>`;
  }

  function documento(logoSrc) {
    const pack = dados();
    const meta = pack.meta || {};
    const janela = Number(meta.janela_metodologica_principal) === 12 ? 12 : 6;
    const geral = serieGeral(janela);
    if (!geral.length) throw new Error("Série da PEONA indisponível.");
    const atual = geral[geral.length - 1];
    const anterior = geral.length > 1 ? geral[geral.length - 2] : null;
    const anoAntes = achar(geral, addMeses(atual.competencia, -12));
    const baseRows = geral.slice(-7, -1);
    const atualMk = LAGS.map(({ j }) => mk(atual, j));
    const baseMk = mediaMk(baseRows.length ? baseRows : geral.slice(0, -1));
    const shifts = deslocamentos(atualMk, baseMk);
    shifts.inicioBase = baseRows[0]?.competencia || geral[0].competencia;
    shifts.fimBase = baseRows[baseRows.length - 1]?.competencia || anterior?.competencia;
    const ctx = {
      geral,
      atual,
      anterior,
      anoAntes,
      seq: sequenciaAltas(geral, "total_avisado", 4),
      shifts,
      testes: testesRecentes(),
    };
    const alertas = montarAlertas(ctx);
    const fx = anterior ? efeitos(atual, anterior) : null;
    const ultimosSeis = geral.slice(-6);
    const antesDaTabela = geral.length > 6 ? geral[geral.length - 7] : null;
    const emissao = dataCurta(meta.gerado_em);
    const logoHtml = logoSrc
      ? `<img class="logo" src="${logoSrc}" alt="Ipasgo Saúde" />`
      : `<p class="logo-texto">Ipasgo Saúde</p>`;

    return `<!DOCTYPE html>
<html lang="pt-BR">
<head>
  <meta charset="UTF-8" />
  <title>\u00a0</title>
  <style>
    @page {
      size: A4;
      margin: 14mm 14mm 18mm;
      @top-left { content: none; }
      @top-center { content: none; }
      @top-right { content: none; }
      @bottom-left { content: none; }
      @bottom-center { content: none; }
      @bottom-right { content: none; }
    }
    * { box-sizing: border-box; }
    body {
      margin: 0;
      color: #2F302A;
      background: #fff;
      font-family: "Segoe UI", Calibri, Arial, sans-serif;
      font-size: 11.5pt;
      line-height: 1.45;
    }
    .acoes {
      position: sticky; top: 0; z-index: 2;
      background: #007940; color: #fff;
      padding: 8px 16px; display: flex; gap: 10px; align-items: center;
    }
    .acoes button {
      background: #C5E838; color: #2F302A; border: 0; border-radius: 6px;
      padding: 7px 12px; font-weight: 700; cursor: pointer;
    }
    .folha { max-width: 920px; margin: 0 auto; padding: 28px 40px 56px; }
    .topo {
      display: flex; justify-content: space-between; align-items: flex-end;
      gap: 16px; padding-bottom: 14px; margin-bottom: 22px;
      border-bottom: 1px solid #e6e1d6;
    }
    .logo { height: 42px; width: auto; display: block; }
    .logo-texto { margin: 0; font-weight: 700; color: #007940; font-size: 16pt; text-align: left; }
    .topo-selo {
      margin: 0; font-size: 8.5pt; letter-spacing: 0.12em; text-transform: uppercase;
      color: #8a867c; font-weight: 600; text-align: right; white-space: nowrap;
    }
    .olho {
      margin: 0 0 6px; font-size: 9pt; letter-spacing: 0.14em; text-transform: uppercase;
      color: #007940; font-weight: 650; text-align: left;
    }
    h1 { margin: 0 0 6px; font-size: 22pt; line-height: 1.15; font-weight: 700; text-align: left; color: #1c1c1a; }
    .sub { margin: 0; color: #5c584e; font-size: 11pt; text-align: left; }
    .meta { margin: 8px 0 0; font-size: 10.5pt; color: #5c584e; text-align: left; }
    h2 {
      margin: 26px 0 8px; font-size: 14pt; color: #1c1c1a; font-weight: 700;
      page-break-after: avoid; text-align: left;
    }
    p { margin: 0 0 8px; text-align: justify; hyphens: auto; }
    .alerta { border-left: 4px solid #007940; background: #f7f6f2; padding: 10px 12px; margin: 0 0 10px; page-break-inside: avoid; }
    .alerta.nivel-alto { border-left-color: #8C3A2F; background: #fbf6f2; }
    .alerta.nivel-atencao { border-left-color: #8A6A12; background: #fbf8ef; }
    .alerta-nivel { margin: 0 0 2px; font-size: 9pt; font-weight: 700; letter-spacing: 0.06em; text-transform: uppercase; color: #5c584e; text-align: left; }
    .alerta h3 { margin: 0 0 4px; font-size: 12pt; text-align: left; }
    .alerta p { text-align: justify; }
    table.tabela { width: 100%; border-collapse: collapse; margin: 10px 0 14px; font-size: 9pt; page-break-inside: avoid; }
    table.tabela th, table.tabela td { padding: 7px 8px; text-align: center; vertical-align: middle; }
    table.tabela th {
      background: #2f3b34; color: #fff; font-weight: 650; line-height: 1.25;
      border: 0;
    }
    table.tabela td { border-bottom: 1px solid #e4dfd4; }
    table.tabela th:first-child, table.tabela td:first-child { text-align: left; }
    table.tabela tbody tr:nth-child(even) td { background: #f3f7ef; }
    footer.rodape {
      margin-top: 28px; padding-top: 8px; border-top: 1px solid #d9d3c7;
      display: flex; justify-content: space-between; gap: 12px;
      font-size: 9pt; color: #5c584e;
    }
    footer.rodape p { margin: 0; text-align: left; }
    @media print {
      .acoes { display: none; }
      .folha { max-width: none; padding: 0 0 16mm; }
      footer.rodape { position: fixed; left: 0; right: 0; bottom: 0; background: #fff; }
    }
  </style>
</head>
<body>
  <div class="acoes">
    <button type="button" onclick="document.title='\u00a0';window.print()">Salvar em PDF</button>
    <span>Na impressão, desmarque “Cabeçalhos e rodapés”.</span>
  </div>
  <article class="folha">
    <header class="topo">
      ${logoHtml}
      <p class="topo-selo">Acompanhamento atuarial</p>
    </header>
    <p class="olho">Acompanhamento atuarial</p>
    <h1>Parecer de acompanhamento atuarial</h1>
    <p class="sub">Provisão de eventos ocorridos e não avisados (PEONA) — apoio à gestão da despesa assistencial</p>
    <p class="meta">Competência de apuração: <strong>${esc(mesLabel(atual.competencia))}</strong> · Janela metodológica: ${janela} meses · Emitido em ${esc(dataEmissao(meta.gerado_em))}</p>

    <h2>1. Objeto</h2>
    <p>Este parecer lê a apuração já calculada da PEONA para explicar, à gestão do plano, por que a despesa assistencial avisada e a provisão se moveram. Os valores são da PEONA geral: médico-hospitalar e odontológico somados. O documento complementa o painel. Ele não substitui o parecer de fechamento da provisão nem uma análise de custo por beneficiário.</p>

    <h2>2. Síntese para a gestão</h2>
    ${htmlAlertas(alertas)}

    <h2>3. Despesa assistencial avisada</h2>
    <p>A despesa avisada é o que a operadora já reconheceu na competência. Ela é a matéria-prima da base média da PEONA. Uma alta persistente aqui é alta de custo assistencial chegando ao caixa técnico do plano.</p>
    ${htmlTabelaMh(ultimosSeis, antesDaTabela)}

    <h2>4. Variação da despesa e da PEONA</h2>
    ${paragrafoDecomposicao(atual, anterior, fx)}

    <h2>5. Ritmo do aviso</h2>
    ${paragrafoMk(atual, shifts, anoAntes)}
    ${htmlTabelaMk(shifts)}

    <h2>6. O que a experiência posterior mostrou</h2>
    ${htmlConsistencia(ctx.testes)}

    <h2>7. Conclusão</h2>
    ${conclusao(ctx, alertas)}

    <h2>8. Limitações</h2>
    <p>A série não traz exposição de beneficiários. A variação comentada é da despesa assistencial avisada e da PEONA do plano, não de um índice per capita. A composição do atraso é a da janela de ${janela} meses, ponderada pela despesa avisada de cada segmento. Ajustes contábeis sem data de ocorrência ou de aviso, quando existirem na base operacional, não aparecem separados neste parecer.</p>

    <footer class="rodape">
      <p>GEPIN · COINI | Corte: ${esc(mesLabel(atual.competencia))} | Emissão: ${esc(emissao)}</p>
      <p>Página 1</p>
    </footer>
  </article>
</body>
</html>`;
  }

  function dataCurta(iso) {
    if (!iso) return "—";
    const d = new Date(iso);
    if (Number.isNaN(d.getTime())) return String(iso).slice(0, 10);
    return d.toLocaleDateString("pt-BR");
  }

  async function carregarLogo() {
    return LOGO_CLARO;
  }

  async function exportarRelatorio() {
    let html;
    try {
      const logo = await carregarLogo();
      html = documento(logo);
    } catch (err) {
      window.alert("Não foi possível montar o relatório. " + (err && err.message ? err.message : ""));
      return;
    }
    const janela = window.open("", "_blank");
    if (!janela) {
      window.alert("O navegador bloqueou a janela do relatório. Permita pop-ups deste painel e tente de novo.");
      return;
    }
    janela.document.open();
    janela.document.write(html);
    janela.document.close();
  }

  document.addEventListener("DOMContentLoaded", () => {
    document.getElementById("btn-export-relatorio")?.addEventListener("click", exportarRelatorio);
  });
})();
